import java.util.*;

class Solution {
    public int numSquares(int n) {
        int[] dp = new int[n + 1];
        Arrays.fill(dp, n + 1);             // sentinel: more than the max possible (n ones)
        dp[0] = 0;
        for (int a = 1; a <= n; a++) {
            for (int s = 1; s * s <= a; s++) {
                dp[a] = Math.min(dp[a], dp[a - s * s] + 1);
            }
        }
        return dp[n];
    }
}

